# the servant: a module-level function over a duck-typed serviced object
def move_to(shape, position: Position) -> None:
    shape.position = position

# the requirement can be declared instead of assumed (checked statically only)
class Movable(Protocol):
    position: Position

def move_by(shape: Movable, dx: int, dy: int) -> None:
    move_to(shape, shape.position.shifted(dx, dy))
